                L[i - 1] = i
        elif shape == 'right':
            for i in range(1, n):
                R[i - 1] = i
        elif shape == 'zig':
            for i in range(1, n):
                if i % 2:
                    L[i - 1] = i
                else:
                    R[i - 1] = i
        elif shape == 'complete':
            for i in range(1, n):
